pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialUnlockTime, uint256 newUnlockTime, uint256 value) public {
        // Keep values within reasonable bounds
        bound(initialUnlockTime, 1, type(uint256).max - 2);
        bound(newUnlockTime, 1, type(uint256).max - 2);
        value = bound(value, 0.1 ether, 10 ether);
        address actor = address(0xbeef);
        vm.deal(actor, 100 ether);

        // Warp to a point in time
        vm.warp(block.timestamp + 1000);

        // First Put with initialUnlockTime
        vm.prank(actor);
        c.Put{value: value}(initialUnlockTime);

        // Warp further, but make newUnlockTime less than current block.timestamp
        vm.warp(block.timestamp + 1000);

        // Second Put with a small newUnlockTime (which should be overridden to block.timestamp)
        uint256 smallTime = block.timestamp - 1; // definitely less than current timestamp
        vm.prank(actor);
        c.Put{value: value}(smallTime);

        // After second Put, unlockTime should be at least block.timestamp (the max of smallTime and block.timestamp)
        // In the buggy version, unlockTime was not updated, so it remains the old initialUnlockTime, which may be less than block.timestamp.
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}

