pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2) public {
        // ensure timestamps are in the future to allow updates
        vm.assume(unlockTime1 >= block.timestamp);
        vm.assume(unlockTime2 >= block.timestamp);
        address sender = address(0x1337);
        vm.deal(sender, 2 ether);

        // first Put
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime1);
        uint storedAfterFirst = c.Acc(sender).unlockTime;

        // second Put with a possibly different unlockTime2
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime2);
        uint storedAfterSecond = c.Acc(sender).unlockTime;

        // expected unlockTime after second Put is the maximum among unlockTime2,
        // block.timestamp (now) and the previously stored unlockTime (since the reference
        // updates it only to max of provided and current timestamp, and the mutant does not update at all)
        uint expected = unlockTime2 > block.timestamp ? unlockTime2 : block.timestamp;
        if (storedAfterFirst > expected) {
            expected = storedAfterFirst;
        }
        assertTrue(storedAfterSecond == expected);
    }
}

