pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2, uint256 warp1, uint256 warp2) public {
        // Bound timestamps to reasonable values (avoid overflow and extreme values)
        unlockTime1 = bound(unlockTime1, 1, type(uint64).max);
        unlockTime2 = bound(unlockTime2, 1, type(uint64).max);
        warp1 = bound(warp1, 1, type(uint64).max);
        warp2 = bound(warp2, 1, type(uint64).max);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);

        // First Put at timestamp warp1
        vm.warp(warp1);
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime1);

        uint storedAfterFirst = c.Acc(sender).unlockTime;

        // Ensure warp2 is >= warp1 to keep the sequence advancing
        vm.assume(warp2 >= warp1);

        // Second Put at timestamp warp2
        vm.warp(warp2);
        vm.prank(sender);
        c.Put{value: 1 ether}(unlockTime2);

        uint storedAfterSecond = c.Acc(sender).unlockTime;

        // Invariant: after two Puts, the final unlockTime must equal the maximum of
        // (unlockTime1, warp1, unlockTime2, warp2). The reference satisfies this;
        // the mutant ignores unlockTime2 and warp2, leaving storedAfterSecond == storedAfterFirst,
        // which breaks the invariant when the second Put would normally increase it.
        uint expectedMax = unlockTime1;
        if (warp1 > expectedMax) expectedMax = warp1;
        if (unlockTime2 > expectedMax) expectedMax = unlockTime2;
        if (warp2 > expectedMax) expectedMax = warp2;

        assertTrue(storedAfterSecond == expectedMax);
    }
}

