pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime) public {
        // Bound amounts to ensure they are >0 and sum does not overflow and unlockTime is in the future
        amount1 = bound(amount1, 1, 1000 ether);
        amount2 = bound(amount2, 1, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 10000);

        // Deploy the reentrant attacker helper
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address attackerAddr = address(attacker);

        // Fund the attacker
        vm.deal(attackerAddr, amount1 + amount2);

        // Perform the attack: attacker calls Put with amount2 which triggers reentrant Put(0) via receive
        attacker.attack{value: amount1 + amount2}(amount2, unlockTime);

        // After the transaction, read the attacker's balance in C
        (uint256 storedUnlockTime, uint256 balance) = c.Acc(attackerAddr);

        // In P, the balance should be amount1 + amount2 (since both Puts succeed and are not reentrant-modifier-blocked)
        // In M, the balance will be amount2 (the reentrant Put fails to increase balance due to buggy NonReentrant)
        // The property: balance == amount1 + amount2 holds for P and fails for M
        assertTrue(balance == amount1 + amount2);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
        attacking = false;
    }

    function attack(uint256 amount, uint256 unlockTime) external payable {
        attacking = true;
        // First Put call with the specified amount and unlockTime, sending all msg.value
        target.Put{value: msg.value}(unlockTime);
        attacking = false;
    }

    // Re-entrancy callback: when C sends Ether via call in Collect, this triggers a second Put
    receive() external payable {
        if (attacking) {
            // Re-entrant call: Put(0) with 0 value
            target.Put{value: 0}(0);
        }
    }
}

