pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Exploit {
    C public target;
    uint256 public exploitAmount;
    bool public reentered;

    constructor(C _target) {
        target = _target;
    }

    function startAttack(uint256 amount) external payable {
        exploitAmount = amount;
        reentered = false;
        target.Put{value: msg.value}(0);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Re-enter Put via the fallback of C, sending the same amount again
            target.Put{value: exploitAmount}(0);
        }
    }
}

contract InvMutTest is Test {
    C c;
    Exploit exploit;

    function setUp() public {
        c = new C(address(this));
        exploit = new Exploit(c);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance / 2);
        vm.assume(amount >= 1 ether);

        // Ensure the exploit contract has enough balance for the attack
        vm.deal(address(exploit), amount * 2);

        uint256 balanceBefore = address(c).balance;

        // Attack: sends 'amount' and re-enters with another 'amount' during Collect callback
        vm.prank(address(exploit));
        exploit.startAttack{value: amount}(amount);

        uint256 balanceAfter = address(c).balance;
        uint256 ethIncrease = balanceAfter - balanceBefore;

        // Rule: The contract can never hold more ETH than the single msg.value sent by the original caller.
        // In correct C, the reentrant Put is blocked, so ethIncrease == amount.
        // In buggy M, the reentrant Put succeeds, so ethIncrease == amount * 2, violating ethIncrease == amount.
        assertTrue(ethIncrease == amount);
    }
}

