import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Assume positive values and collectAmount <= putAmount to keep the scenario simple
        vm.assume(putAmount > 0 && putAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(unlockTime > block.timestamp);

        // Deploy a re-entrant attacker that calls Collect again during the first Collect
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        vm.deal(address(attacker), putAmount);

        // Warp to a time before unlock to ensure the unlockTime condition can be satisfied later
        vm.warp(0);

        // Attacker puts funds
        vm.startPrank(address(attacker));
        c.Put{value: putAmount}(unlockTime);
        vm.stopPrank();

        // Warp past the unlock time to allow collection
        vm.warp(unlockTime + 1);

        // Attacker initiates the reentrant Collect
        attacker.attack(collectAmount);

        // After the attack, the attacker's balance in Acc should equal address(c).balance
        // for the reference contract, but not for the mutant (balance drained but Acc.balance not fully reduced)
        uint256 accBalance = c.Acc(address(attacker));
        assertTrue(accBalance == address(c).balance);
    }
}

